// ── Configuration ──────────────────────────────────────────────
const CRITICAL_TAG = '[critical]'; // mark workflows by name, e.g. "Invoice Sync [critical]"
const CRITICAL_KEYWORDS = ['payment', 'billing', 'invoice']; // name keywords that are always critical
// ───────────────────────────────────────────────────────────────

const data = $json;

const workflowName = data.workflow?.name ?? 'Unknown workflow';
const workflowId = data.workflow?.id ?? '';
const executionId = data.execution?.id ?? '';
const executionUrl = data.execution?.url ?? '';
const nodeName = data.execution?.lastNodeExecuted ?? 'Unknown node';
const errorMessage =
  data.execution?.error?.message ??
  data.trigger?.error?.message ??
  'Unknown error';

const nameLower = workflowName.toLowerCase();
const isCritical =
  nameLower.includes(CRITICAL_TAG.toLowerCase()) ||
  CRITICAL_KEYWORDS.some((kw) => nameLower.includes(kw.toLowerCase()));

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      severity: isCritical ? 'critical' : 'warning',
      workflowName,
      workflowId,
      executionId,
      executionUrl,
      nodeName,
      errorMessage,
      isCritical,
    },
  },
];

